f['io/tvos/ContinueHarness.java']='''package io.tvos;import java.util.*;import android.view.KeyEvent;import android.graphics.Canvas;public class ContinueHarness {static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[] args){int[] opens={0},tops={0};DockContinue row=new DockContinue(new android.content.Context(),()->{},Runnable::run);List<Recs.Pick> list=new ArrayList<>();for(int i=0;i<12;i++){Recs.Pick p=new Recs.Pick();p.title="Film"+i;p.watchingKey="kinopub:"+i;p.resumeUri="intent:"+i;p.pkg="watch.kino.mod";list.add(p);}row.show(list);android.animation.ValueAnimator entrance=android.animation.ValueAnimator.last;check(entrance.delay==400&&entrance.duration==320,"row waits for previous banner before fading in");Canvas hidden=new Canvas();row.draw(hidden,1,810,0,true);check(hidden.entries.isEmpty(),"row cannot overlap outgoing banner during delay");entrance.fraction(1);check(DockArtwork.calls==4,"prefetch bounded to four cards");row.show(list);check(DockArtwork.calls==4,"same snapshot does not repeat metadata queries");java.util.function.Consumer<Recs.Pick> open=p->{check(p==list.get(2),"resume original provider pick");opens[0]++;};Runnable top=()->tops[0]++;check(!row.key(new KeyEvent(0,19),false,top,open),"top controls do not enter row");check(row.key(new KeyEvent(0,19),true,top,open),"up from Dock enters cards");android.animation.ValueAnimator focus=android.animation.ValueAnimator.last;Canvas beforeFocus=new Canvas();row.draw(beforeFocus,1,810,0,true);focus.fraction(.5f);Canvas middleFocus=new Canvas();row.draw(middleFocus,1,810,0,true);float baseWidth=beforeFocus.entries.stream().filter(e->e.kind.equals("bitmap")).findFirst().get().r-beforeFocus.entries.stream().filter(e->e.kind.equals("bitmap")).findFirst().get().l;Canvas.Entry enlarged=middleFocus.entries.stream().filter(e->e.kind.equals("bitmap")).findFirst().get();check(Math.abs((enlarged.r-enlarged.l)/baseWidth-1.025f)<.001f,"focus grows smoothly halfway to five percent");focus.fraction(1);row.key(new KeyEvent(1,19),true,top,open);row.key(new KeyEvent(1,23),true,top,open);check(opens[0]==0,"stray OK release does not launch");row.key(new KeyEvent(0,22),true,top,open);row.key(new KeyEvent(0,22),true,top,open);row.key(new KeyEvent(0,23),true,top,open);row.key(new KeyEvent(1,23),true,top,open);check(opens[0]==1,"OK resumes selected card once");Canvas c=new Canvas();row.draw(c,1,810,0,true);check(c.entries.stream().anyMatch(e->e.kind.equals("text")&&e.text.equals("Continue Watching")),"localized heading");check(PosterCache.max<=4,"bitmap window bounded");java.util.List<Canvas.Entry> frames=c.entries.stream().filter(e->e.kind.equals("round")&&e.color==0xFF343A3D).toList();check(frames.size()>=2&&frames.get(1).r<=1880.01f,"two settled cards fit inside right forty-pixel inset");check(c.entries.stream().filter(e->e.kind.equals("bitmap")).allMatch(e->e.alpha==0),"newly decoded pictures start transparent");android.os.SystemClock.now+=120;Canvas imageHalf=new Canvas();row.draw(imageHalf,1,810,0,true);check(imageHalf.entries.stream().anyMatch(e->e.kind.equals("bitmap")&&Math.abs(e.alpha-128)<=1),"pictures fade in after decoding");android.os.SystemClock.now+=120;android.animation.ValueAnimator a=android.animation.ValueAnimator.last;check(a.duration==360&&((android.view.animation.DecelerateInterpolator)a.easing).factor==1.5f,"horizontal movement uses deceleration");Canvas start=new Canvas();row.draw(start,1,810,0,true);a.fraction(.5f);Canvas halfway=new Canvas();row.draw(halfway,1,810,0,true);java.util.List<Canvas.Entry> before=start.entries.stream().filter(e->e.kind.equals("bitmap")).toList(),after=halfway.entries.stream().filter(e->e.kind.equals("bitmap")).toList();check(after.get(0).l<before.get(0).l,"cards translate horizontally during animation");check(Math.abs((after.get(0).r-after.get(0).l)-(before.get(0).r-before.get(0).l))<.01f,"card image scale stays fixed while scrolling");Canvas.Entry heading=halfway.entries.stream().filter(e->e.kind.equals("text")&&e.text.equals("Continue Watching")).findFirst().get();check(heading.t==260&&heading.size==54,"heading returns lower with fifty-percent larger text");a.fraction(1);row.key(new KeyEvent(0,20),true,top,open);check(!row.key(new KeyEvent(0,22),true,top,open),"down returns horizontal navigation to Dock");row.hide();check(!row.visible()&&PosterCache.window.isEmpty(),"hide clears image window and focus");check(!row.key(new KeyEvent(0,19),true,top,open),"disabled row never intercepts navigation");System.out.println("PASS: Dock resume navigation, saved links, bounded prefetch, localization and lifecycle");}}'''
with tempfile.TemporaryDirectory() as d:
 root=Path(d);write(root)
